#!/bin/bash
# Task 109-w26-jumpmap-29 -- meshsim WORKER26: the host-side inputs of the Tracer's bring-up (B1) at 2^29, into PERSISTENT
# data ($DATA below; Quest PIPELINE.md): for evm-zone-29 and cyclone-29, gold's segment file, the per-proof jump-target
# table (map.lines, frame6.bin), the initial image (initial.pages), the per-segment lists of pages written (seg/NNN.pages)
# and proof.json (word 66's values, the hash constants), in WORKER22's layout (meshsim WORKER26/NOTES.md).
# The embedded kit (SHA-256 checked) holds gold (7ef9039) and jumpmap (meshsim v1.3-jumpmap) compiled with Java 21
# (the runner has no javac), both programs and their 2^29 inputs (jolt-asic-planning tracer-standalone-main fa59d9a).
# jumpmap checks every jump through the Tracer's probe and every segment's start memory against gold; every output's
# SHA-256 must equal WORKER26's local run. Writes: $DATA/w26-jumpmap/{evm-zone-29/, cyclone-29/, <p>.COMPLETE, manifest.sha256}
# Reboot-safe: each run is written to a staging directory and moved into place only when complete and checked; a re-run
# skips a run whose COMPLETE marker matches its manifest. Expected ~3 min.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD
RES=$REPO/results/109-w26-jumpmap-29; mkdir -p "$RES"
DATA=$HOME/data
{ mkdir -p "$DATA" && touch "$DATA/.writable" && rm -f "$DATA/.writable"; } 2>/dev/null || DATA=$REPO/data
mkdir -p "$DATA" || { echo "no writable persistent data directory ($HOME/data, $REPO/data)"; exit 4; }
echo "persistent data: $DATA" | tee "$RES/data_path.txt"
WANT=7c0216c76c85fce2e51cd3d8f7bd67dcd59761beb52e79710903e5b5bee4b98f
W=/tmp/w26-109; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__TGZ_BEGIN__$/,/^__TGZ_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "$WANT" ] || { echo "kit sha256 mismatch (want $WANT)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
cat "$W/w26/VERSION"; echo "start $(date -u) on $(hostname), $(nproc) threads"; java -version 2>&1 | head -1
CP="$W/w26/classes"
OUT=$DATA/w26-jumpmap; mkdir -p "$OUT"
RC=0
run() {  # run NAME GUEST SEG_SHA MAP_SHA F6_SHA INIT_SHA SEGLISTS_SHA
  local P=$1 G=$W/w26/guests/$2 ST=$OUT/.staging-$1
  if [ -f "$OUT/$P.COMPLETE" ] && [ -f "$OUT/$P/manifest.sha256" ] && \
     [ "$(cat "$OUT/$P.COMPLETE")" = "$(sha256sum "$OUT/$P/manifest.sha256" | cut -d' ' -f1)" ]; then
    echo "$P: complete already ($(cat "$OUT/$P.COMPLETE")), skipped"; return 0
  fi
  rm -rf "$ST"; mkdir -p "$ST"
  java -Xmx4g -cp "$CP" gold.Main segments "$G" "$G/input" "$ST/segments.seg" > "$RES/$P-gold.log" 2>&1 || { echo "$P: gold failed"; tail -3 "$RES/$P-gold.log"; return 1; }
  tail -1 "$RES/$P-gold.log"
  java -Xmx4g -cp "$CP" jumpmap.Main "$G" "$G/input" "$ST/segments.seg" "$ST" --name=$P --gold-commit=7ef9039 > "$RES/$P-jumpmap.log" 2>&1
  local jrc=$?; grep -v '^  [a-z+]' "$RES/$P-jumpmap.log"
  [ $jrc = 0 ] || { echo "$P: jumpmap failed (exit $jrc)"; return 1; }
  cp "$ST/report.json" "$RES/$P-report.json"; cp "$ST/segments.csv" "$RES/$P-segments.csv"; cp "$ST/proof.json" "$RES/$P-proof.json"
  local bad=0
  chk() { local got; got=$(sha256sum "$2" | cut -d' ' -f1); [ "$got" = "$3" ] && echo "$P: $1 ok ($got)" || { echo "$P: $1 MISMATCH ($got, want $3)"; bad=1; }; }
  chk segments.seg "$ST/segments.seg" $3
  chk map.lines "$ST/map.lines" $4
  chk frame6.bin "$ST/frame6.bin" $5
  chk initial.pages "$ST/initial.pages" $6
  cat "$ST"/seg/*.pages > "$W/seglists"; chk "seg/*.pages (concatenated)" "$W/seglists" $7
  [ "$(grep -l '"gold_check": "ok"' "$ST"/seg/*.json | wc -l)" = 128 ] && echo "$P: gold_check ok at all 128 segments" || { echo "$P: gold_check not ok everywhere"; bad=1; }
  [ $bad = 0 ] || return 1
  (cd "$ST" && find . -type f ! -name manifest.sha256 | sort | xargs sha256sum > manifest.sha256)
  rm -f "$OUT/$P.COMPLETE"; rm -rf "$OUT/$P"; mv "$ST" "$OUT/$P" || return 1
  sha256sum "$OUT/$P/manifest.sha256" | cut -d' ' -f1 > "$OUT/$P.COMPLETE"
  cp "$OUT/$P/manifest.sha256" "$RES/$P-manifest.sha256"
  echo "$P: in place at $OUT/$P ($(du -sh "$OUT/$P" | cut -f1)), COMPLETE $(cat "$OUT/$P.COMPLETE")"
}
run evm-zone-29 evm-zone 208520ece5475cafff6e89caffe716be3346eb45f3189b0383e6f1668aa17d18 \
  10c146d0380f690b24959e4c0bc8d94f45439258c6facf2f5d0b3e170fe09a6c d3e646b2329ed07b2cc45abb003b265f28154b39c08a3ed87b030add0225eac6 \
  51aaea2f2be6f892a75fa509a2e1a67aca4ce02c9fb5a4e1d695e9efaaa29401 56b63dd683f960e21e05ad29d916765baf7feddc83267f548b6ce5bb48b44b94 || RC=5
run cyclone-29 cyclone f45f71b6e5359960829a901aacf08569e690fc3d8139dc17858fb0df8aa64070 \
  ef286e0c9d0c96dcab628bf2a3e6c3975f4ab5f680ee737dabbec2025df1a68e 1a0c646e58a994b697f860f0fe4aedda36834e63a0ae91e00d24565460962464 \
  6f7438cd73cae839a80173d20cc80e353cf490301441e9a385cd252ff164932a d7679f6f63a4ed734e966b8c72e22e5b46126a82baf3403c3e85d3b4d826dc84 || RC=5
(cd "$OUT" && cat evm-zone-29.COMPLETE cyclone-29.COMPLETE 2>/dev/null > /dev/null && \
  { for p in evm-zone-29 cyclone-29; do sed "s#  \./#  $p/#" $p/manifest.sha256; done > manifest.sha256; cp manifest.sha256 "$RES/manifest.sha256"; })
echo "end $(date -u), exit $RC"
rm -rf "$W"
exit $RC
